    InboundInputMetadata,
    OutboundInputMetadata,
    WebInputMetadata,
    PlaygroundInputMetadata,
]


def parse_input_metadata(metadata_json: str) -> InputMetadata:
    """Parse input metadata from JSON string"""
    try:
        data = json.loads(metadata_json)
        kind = data.get("kind", CallKind.WEB)
        match kind:
            case CallKind.INBOUND:
                return InboundInputMetadata(**data)
            case CallKind.OUTBOUND:
                return OutboundInputMetadata(**data)
            case CallKind.PLAYGROUND:
                return PlaygroundInputMetadata(**data)
            case _:
                return WebInputMetadata(**data)
