    data = base_data.copy()
    if additional_data:
        data.update(additional_data)

    if kind == CallKind.INBOUND:
        return InboundInputMetadata(**data)
    elif kind == CallKind.OUTBOUND:
        return OutboundInputMetadata(**data)
    elif kind == CallKind.PLAYGROUND:
        return PlaygroundInputMetadata(**data)
    else:
        return WebInputMetadata(**data)


