def parse_agent_room_metadata(metadata_json: str) -> AgentRoomMetadata:
    """Parse agent room metadata from JSON string"""
    try:
        data = json.loads(metadata_json)

        # Check if this is local dev metadata
        if "internal_call_script_local_path" in data and "input_metadata" not in data:
            return LocalDevAgentRoomMetadata(**data)

        # Otherwise it should be screening metadata with input_metadata
        if "input_metadata" in data:
            input_metadata = parse_input_metadata(json.dumps(data["input_metadata"]))
            return ScreeningAgentRoomMetadata(
                input_metadata=input_metadata,
                engagement_id=data["engagement_id"],
            )

        # Fallback: treat as input metadata and wrap in screening metadata
        input_metadata = parse_input_metadata(metadata_json)
        return ScreeningAgentRoomMetadata(
            input_metadata=input_metadata,
            engagement_id=data.get("engagement_id", ""),
        )
    except (json.JSONDecodeError, ValueError) as e:
        logger.warning(
            "Unable to parse agent room metadata, using default",
            raw_data=metadata_json,
            error=str(e),
        )
        # Return a default
        return ScreeningAgentRoomMetadata(
            input_metadata=PlaygroundInputMetadata(
                agent=AgentType.SCREENING,
                engagement_id=None,
                opportunity_id="",
            ),
            engagement_id="",
        )

